import fs from'node:fs';import{loadAnny,json,bytes,gunzip}from'../teachers.mjs';import{MHRDetailedEngine,unpackModel}from'./MHRDetailedEngine.mjs';import{MHRBodyAdapter}from'./MHRBodyAdapter.mjs';
const read=(n,T)=>{const b=fs.readFileSync(new URL(n,import.meta.url));return new T(b.buffer.slice(b.byteOffset,b.byteOffset+b.byteLength));};
export function createBodyAdapter({mappingDirectory=null}={}){const dir=mappingDirectory?new URL(mappingDirectory,import.meta.url):new URL('./',import.meta.url),readMap=(n,T)=>{const b=fs.readFileSync(new URL(n,dir));return new T(b.buffer.slice(b.byteOffset,b.byteOffset+b.byteLength));};const meta=json('kaopu-mhr-workbench/assets/model.json'),engine=new MHRDetailedEngine(meta,unpackModel(meta,bytes('mhr-model.raw.bin'))),canonical=JSON.parse(new TextDecoder().decode(gunzip('kaopu-unified-human-workbench/assets/canonical.json.gz'))),map=JSON.parse(fs.readFileSync(new URL('mapping-report.json',dir)));return new MHRBodyAdapter({engine,anny:loadAnny(),canonical,mapIndices:readMap('map-indices.u32',Uint32Array),mapBary:readMap('map-bary.f32',Float32Array),topologySha256:map.topologySha256});}
